create table public.organization_settings (
 organization_id uuid not null references public.organizations(id),
 section text not null check (section in ('kurum','kayit','ders','gruplar','sistem')),
 config jsonb not null default '{}' check (jsonb_typeof(config) = 'object'),
 revision integer not null default 1 check (revision > 0),
 updated_by uuid references public.profiles(id), updated_at timestamptz not null default now(),
 primary key (organization_id,section)
);
create table public.organization_settings_history (
 id bigint generated always as identity primary key,
 organization_id uuid not null references public.organizations(id), section text not null,
 old_values jsonb, new_values jsonb not null, revision integer not null,
 changed_by uuid references public.profiles(id), changed_at timestamptz not null default now(),
 unique(organization_id,section,revision)
);
create index organization_settings_history_recent on public.organization_settings_history(organization_id,changed_at desc);
alter table public.organization_settings enable row level security;
alter table public.organization_settings_history enable row level security;
revoke all on public.organization_settings, public.organization_settings_history from anon, authenticated;
grant select on public.organization_settings to authenticated;
grant select on public.organization_settings_history to authenticated;
grant all on public.organization_settings, public.organization_settings_history to service_role;
grant usage,select on sequence public.organization_settings_history_id_seq to service_role;
create policy settings_read_own_org on public.organization_settings for select to authenticated using (organization_id in (select organization_id from public.profiles where id = (select auth.uid())));
create policy settings_history_admin on public.organization_settings_history for select to authenticated using (organization_id in (select organization_id from public.profiles where id = (select auth.uid()) and role::text in ('owner','admin')));
create function public.save_organization_settings(p_organization_id uuid,p_section text,p_values jsonb,p_revision integer,p_actor uuid) returns integer
language plpgsql security invoker set search_path = '' as $$
declare old_config jsonb; next_revision integer;
begin
 if not exists(select 1 from public.profiles where id=p_actor and organization_id=p_organization_id and is_active and (role::text in ('owner','admin') or exists(select 1 from public.staff where auth_user_id=p_actor and is_active and login_enabled and is_super_user))) then raise exception 'Yetkisiz ayar değişikliği'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_organization_id::text || ':' || p_section,0));
 select config into old_config from public.organization_settings where organization_id=p_organization_id and section=p_section;
 insert into public.organization_settings(organization_id,section,config,revision,updated_by)
 select p_organization_id,p_section,p_values,1,p_actor where p_revision=0
 on conflict(organization_id,section) do nothing;
 if not found then
  update public.organization_settings set config=p_values,revision=revision+1,updated_by=p_actor,updated_at=now()
  where organization_id=p_organization_id and section=p_section and revision=p_revision and p_revision>0;
  if not found then raise exception 'Ayarlar başka bir oturumda değiştirildi. Sayfayı yenileyin.'; end if;
 end if;
 select revision into next_revision from public.organization_settings where organization_id=p_organization_id and section=p_section;
 insert into public.organization_settings_history(organization_id,section,old_values,new_values,revision,changed_by) values(p_organization_id,p_section,old_config,p_values,next_revision,p_actor);
 return next_revision;
end $$;
revoke all on function public.save_organization_settings(uuid,text,jsonb,integer,uuid) from public, anon, authenticated;
grant execute on function public.save_organization_settings(uuid,text,jsonb,integer,uuid) to service_role;

insert into public.message_templates(organization_id,template_key,title,body,channel,is_active,version) select o.id,t.key,t.title,t.body,'whatsapp',true,1 from public.organizations o cross join jsonb_to_recordset('[{"key":"registration_completed","title":"Kayıt Tamamlandı","body":"*SPRİNT YÜZME OKULU | KAYIT BİLGİLENDİRMESİ*\n\nDeğerli Velimiz,\n\n*{ogrenci_adi}* öğrencimizin kaydı başarıyla tamamlanmıştır. 💙\n\n🏊 *Şube:* {sube}\n👥 *Grup:* {grup}\n🗓️ *Program:* {program}\n📅 *Başlangıç:* {baslangic_tarihi}\n🏁 *Planlanan bitiş:* {bitis_tarihi}\n\nDers programınız ve kayıt bilgileriniz SprintOS kursiyer dosyanıza işlenmiştir.\n\n*SPRİNT YÜZME OKULU*\nBilgilendirme Hattı: 0551 896 83 19"},{"key":"renewal","title":"Kayıt Yenileme","body":"*SPRİNT YÜZME OKULU | KAYIT YENİLEME*\n\nDeğerli Velimiz,\n\n*{ogrenci_adi}* öğrencimizin mevcut yüzme programında kalan ders hakkı *{kalan_ders} ders*tir.\n\n🏊 *Şube:* {sube}\n👥 *Grup:* {grup}\n🗓️ *Program:* {program}\n🏁 *Planlanan bitiş:* {bitis_tarihi}\n\nEğitimin kesintisiz devam etmesi için kayıt yenileme işleminizi tamamlayabilirsiniz.\n\n*SPRİNT YÜZME OKULU*\nBilgilendirme Hattı: 0551 896 83 19"},{"key":"freeze","title":"Kayıt Durumu Bilgilendirmesi","body":"*SPRİNT YÜZME OKULU | KAYIT DURUMU*\n\nDeğerli Velimiz,\n\n*{ogrenci_adi}* öğrencimizin kayıt durumuyla ilgili bilgilendirme için sizinle iletişime geçiyoruz.\n\n🏊 *Şube:* {sube}\n👥 *Grup:* {grup}\n🗓️ *Program:* {program}\n\nDetaylı bilgi için Sprint Yüzme Okulu ile iletişime geçebilirsiniz.\n\n*SPRİNT YÜZME OKULU*\n0551 896 83 19"},{"key":"compensation","title":"Telafi Dersi","body":"*SPRİNT YÜZME OKULU | TELAFİ DERSİ*\n\nDeğerli Velimiz,\n\n*{ogrenci_adi}* öğrencimiz için telafi dersi sistemimize eklenmiştir.\n\n🟣 *Telafi tarihi:* {telafi_tarihi}\n🏊 *Telafi grubu:* {telafi_grubu}\n🕐 *Telafi saati:* {telafi_saati}\n📌 *Normal planlanan bitiş:* {normal_bitis_tarihi}\n✅ *Güncel planlanan bitiş:* {bitis_tarihi}\n\nDers hakkınız kursiyer dosyanızda korunmaktadır.\n\n*SPRİNT YÜZME OKULU*\n0551 896 83 19"},{"key":"absence","title":"Derse Katılım Bilgilendirmesi","body":"*SPRİNT YÜZME OKULU | DERS KATILIMI*\n\nDeğerli Velimiz,\n\n*{ogrenci_adi}* öğrencimizin *{son_devamsizlik_tarihi}* tarihli dersimize katılım sağlayamadığı görülmektedir.\n\n🏊 *Şube:* {sube}\n👥 *Grup:* {grup}\n🗓️ *Program:* {program}\n\nBir sonraki dersiniz mevcut program doğrultusunda devam edecektir.\n\n*SPRİNT YÜZME OKULU*\n0551 896 83 19"},{"key":"payment","title":"Ödeme Bilgilendirmesi","body":"*SPRİNT YÜZME OKULU | ÖDEME BİLGİLENDİRMESİ*\n\nDeğerli Velimiz,\n\n*{ogrenci_adi}* öğrencimizin ödeme durumuna ilişkin güncel bilgi aşağıdadır.\n\n💳 *Kalan ödeme:* {kalan_odeme}\n📅 *Vade tarihi:* {vade_tarihi}\n🏊 *Şube:* {sube}\n👥 *Grup:* {grup}\n\nÖdeme yaptıysanız bu mesajı dikkate almayabilirsiniz. Detaylı bilgi için bize ulaşabilirsiniz.\n\n*SPRİNT YÜZME OKULU*\n0551 896 83 19"},{"key":"bank_info","title":"IBAN / Ödeme Bilgileri","body":"*SPRİNT YÜZME OKULU | ÖDEME BİLGİLERİ*\n\nDeğerli Kursiyerimiz,\n\nÖdemenizi gerçekleştirebilmeniz için banka hesap bilgilerimizi aşağıda paylaşıyoruz.\n\n🏦 *Banka:* VakıfBank\n👤 *Hesap Sahibi:* Nuran Uçar\n💳 *IBAN:* TR14 0001 5001 5800 7357 4815 06\n\nÖdemenizi tamamladıktan sonra ayrıca bir işlem yapmanız gerekmemektedir. Dilerseniz ödeme dekontunuzu bu WhatsApp hattı üzerinden bizimle paylaşabilirsiniz.\n\nSorularınız için bize her zaman ulaşabilirsiniz.\n\n*SPRİNT YÜZME OKULU*\nBilgilendirme Hattı: 0551 896 83 19"},{"key":"lesson_ending","title":"Ders Hakkı Azaldı","body":"*SPRİNT YÜZME OKULU | DERS HAKKI BİLGİLENDİRMESİ*\n\nDeğerli Velimiz,\n\n*{ogrenci_adi}* öğrencimizin paketinde *{kalan_ders} ders* kalmıştır.\n\n🏁 *Planlanan bitiş:* {bitis_tarihi}\n🏊 *Şube:* {sube}\n👥 *Grup:* {grup}\n🗓️ *Program:* {program}\n\nEğitimin kesintisiz sürmesi için kayıt yenileme işleminizi planlayabilirsiniz.\n\n*SPRİNT YÜZME OKULU*\n0551 896 83 19"},{"key":"lesson_finished","title":"Ders Hakkı Tamamlandı","body":"*SPRİNT YÜZME OKULU | PAKET TAMAMLANDI*\n\nDeğerli Velimiz,\n\n*{ogrenci_adi}* öğrencimizin mevcut paketindeki ders hakları tamamlanmıştır.\n\n🏊 *Şube:* {sube}\n👥 *Grup:* {grup}\n🗓️ *Program:* {program}\n\nYeni dönem kayıt ve program bilgisi için bizimle iletişime geçebilirsiniz.\n\n*SPRİNT YÜZME OKULU*\n0551 896 83 19"},{"key":"program","title":"Program Bilgilendirmesi","body":"*SPRİNT YÜZME OKULU | PROGRAM BİLGİLENDİRMESİ*\n\nDeğerli Velimiz,\n\n*{ogrenci_adi}* öğrencimizin güncel yüzme programı aşağıdaki gibidir.\n\n🏊 *Şube:* {sube}\n👥 *Grup:* {grup}\n🗓️ *Program:* {program}\n\nDerslerinize belirtilen gün ve saatte devam edebilirsiniz.\n\n*SPRİNT YÜZME OKULU*\n0551 896 83 19"},{"key":"pool_closed","title":"Havuz Kapalı","body":"*SPRİNT YÜZME OKULU | DERS BİLGİLENDİRMESİ*\n\nDeğerli Velimiz,\n\n*{sube}* şubemizdeki *{program}* seansımız tesis yönetimi kaynaklı kapanış nedeniyle gerçekleştirilemeyecektir.\n\nDers hakkınız sisteminizde korunacaktır. Diğer şubelerimizdeki derslerimiz planlandığı şekilde devam etmektedir.\n\n*SPRİNT YÜZME OKULU*\nBilgilendirme Hattı: 0551 896 83 19"},{"key":"hygiene","title":"Hijyen / Bakım Nedeniyle Ders İptali","body":"*SPRİNT YÜZME OKULU | TESİS BİLGİLENDİRMESİ*\n\nDeğerli Velimiz,\n\n*{sube}* şubemizdeki *{program}* seansımız tesis yönetiminin hijyen / bakım çalışması nedeniyle bugün gerçekleştirilemeyecektir.\n\nİptal edilen ders hakkınız sisteminize telafi olarak eklenecek ve ayrıca bilgilendirileceksiniz.\n\n*SPRİNT YÜZME OKULU*\n0551 896 83 19"},{"key":"technical","title":"Teknik Nedenle Ders İptali","body":"*SPRİNT YÜZME OKULU | TESİS BİLGİLENDİRMESİ*\n\nDeğerli Velimiz,\n\n*{sube}* şubemizdeki *{program}* seansımız tesis kaynaklı teknik çalışma nedeniyle bugün gerçekleştirilemeyecektir.\n\nDers hakkınız korunacak ve telafi planı ayrıca bildirilecektir.\n\n*SPRİNT YÜZME OKULU*\n0551 896 83 19"},{"key":"group_transfer","title":"Grup / Şube Aktarımı","body":"*SPRİNT YÜZME OKULU | PROGRAM GÜNCELLEMESİ*\n\nDeğerli Velimiz,\n\n*{ogrenci_adi}* öğrencimizin yüzme programı güncellenmiştir.\n\n🏊 *Yeni şube:* {sube}\n👥 *Yeni grup:* {grup}\n🗓️ *Yeni program:* {program}\n📅 *Geçiş tarihi:* {gecis_tarihi}\n🏁 *Güncel planlanan bitiş:* {bitis_tarihi}\n\nKalan ders haklarınız yeni programınıza aktarılmıştır.\n\n*SPRİNT YÜZME OKULU*\n0551 896 83 19"},{"key":"time_change","title":"Seans / Saat Değişikliği","body":"*SPRİNT YÜZME OKULU | SAAT DEĞİŞİKLİĞİ*\n\nDeğerli Velimiz,\n\n*{ogrenci_adi}* öğrencimizin güncel ders programı *{program}* olarak düzenlenmiştir.\n\n🏊 *Şube:* {sube}\n👥 *Grup:* {grup}\n\nDerslerinize yeni program doğrultusunda devam edebilirsiniz.\n\n*SPRİNT YÜZME OKULU*\n0551 896 83 19"},{"key":"coach_change","title":"Antrenör Bilgilendirmesi","body":"*SPRİNT YÜZME OKULU | ANTRENÖR BİLGİLENDİRMESİ*\n\nDeğerli Velimiz,\n\n*{ogrenci_adi}* öğrencimizin *{program}* seansına ilişkin antrenör görevlendirmesinde güncelleme yapılmıştır.\n\n🏊 *Şube:* {sube}\n👥 *Grup:* {grup}\n\nDers programınızda başka bir değişiklik bulunmamaktadır.\n\n*SPRİNT YÜZME OKULU*\n0551 896 83 19"},{"key":"gift","title":"SPRİNT Hediye Ders","body":"🎁 *SPRİNT YÜZME OKULU''NDAN HEDİYE DERS*\n\nDeğerli Velimiz,\n\n*{ogrenci_adi}* öğrencimiz için SPRİNT YÜZME OKULU tarafından *{hediye_ders} adet yüzme dersi* hediye edilmiştir. 💙\n\n🏊 *Grup:* {grup}\n🗓️ *Ders planı:* {program}\n📌 *Önceki planlanan bitiş:* {normal_bitis_tarihi}\n✅ *Yeni planlanan bitiş:* {bitis_tarihi}\n\nHediye dersleriniz sisteminize işlenmiş ve ders hakkınıza eklenmiştir.\n\n*SPRİNT YÜZME OKULU*\n0551 896 83 19"},{"key":"general","title":"Genel Duyuru","body":"*SPRİNT YÜZME OKULU | BİLGİLENDİRME*\n\nDeğerli Velimiz,\n\n{mesaj}\n\n*SPRİNT YÜZME OKULU*\nBilgilendirme Hattı: 0551 896 83 19"}]'::jsonb) as t(key text,title text,body text) where o.is_active on conflict(organization_id,template_key) do nothing;
create function public.save_settings_message_template(p_organization_id uuid,p_key text,p_title text,p_body text,p_version integer,p_actor uuid) returns integer
language plpgsql security invoker set search_path = '' as $$
declare old_config jsonb; next_version integer;
begin
 if not exists(select 1 from public.profiles where id=p_actor and organization_id=p_organization_id and is_active and (role::text in ('owner','admin') or exists(select 1 from public.staff where auth_user_id=p_actor and is_active and login_enabled and is_super_user))) then raise exception 'Yetkisiz ayar değişikliği'; end if;
 select jsonb_build_object('title',title,'body',body) into old_config from public.message_templates where organization_id=p_organization_id and template_key=p_key for update;
 update public.message_templates set title=p_title,body=p_body,version=version+1,updated_at=now() where organization_id=p_organization_id and template_key=p_key and version=p_version returning version into next_version;
 if not found then raise exception 'Şablon başka bir oturumda değiştirildi. Sayfayı yenileyin.'; end if;
 insert into public.organization_settings_history(organization_id,section,old_values,new_values,revision,changed_by) values(p_organization_id,'mesaj/'||p_key,old_config,jsonb_build_object('title',p_title,'body',p_body),next_version,p_actor);
 return next_version;
end $$;
revoke all on function public.save_settings_message_template(uuid,text,text,text,integer,uuid) from public, anon, authenticated;
grant execute on function public.save_settings_message_template(uuid,text,text,text,integer,uuid) to service_role;
